482	+import { isIpad } from "shared/utils";
483	+import { NavigationContainerRef } from "../const";
484	+
485	+export const openRoom = (roomId: string) => {
486	+  if (isIpad()) {
487	+    const route = NavigationContainerRef.getCurrentRoute();
488	+    if (route?.name !== "home") NavigationContainerRef.navigate("home");
489	+    getDefaultStore().set(RoomAtoms.selectedRoomId, roomId);
490	+    return;
491	+  }
492	+
493	+  NavigationContainerRef.navigate("room", { roomId });
494	+};
495	+
496	+/** Reset the navigation stack so the user lands on the room. On iPad the stack
497	+ * is reset to home and the room is shown in the right pane via the selected
498	+ * room atom. */
499	+export const resetToRoom = (roomId: string) => {
500	+  if (isIpad()) {
501	+    NavigationContainerRef.reset({
502	+      index: 0,
503	+      routes: [{ name: "home" }],
504	+    });
505	+    getDefaultStore().set(RoomAtoms.selectedRoomId, roomId);
506	+    return;
507	+  }
508	+
509	+  NavigationContainerRef.reset({
510	+    index: 1,
511	+    routes: [{ name: "home" }, { name: "room", params: { roomId } }],
512	+  });
513	+};
