1412	+import { IpadSidebar } from "../ipad-sidebar";
1413	+
1414	+const SIDEBAR_WIDTH = 440;
1415	+
1416	+const FULLSCREEN_ROUTES: (keyof Routes)[] = [
1417	+  "splash",
1418	+  "welcome",
1419	+  "login",
1420	+  "onboarding",
1421	+  "notificationsIntro",
1422	+  "serverSelect",
1423	+  "confirmIdentity",
1424	+  "cantConfirm",
