1431	+export const IpadLayoutWrapper: React.FC<PropsWithChildren> = ({
1432	+  children,
1433	+}) => {
1434	+  const ipad = isIpad();
1435	+  const splashFinished = useAtomValue(NavigationAtoms.splashFinished);
1436	+  const matrixClient = useAtomValue(MatrixAtoms.matrixClient);
1437	+  const [currentRoute, setCurrentRoute] = useState<string | undefined>(
1438	+    undefined,
1439	+  );
1440	+  const currentRouteRef = useRef<string | undefined>(undefined);
1441	+
1442	+  const showSidebar =
1443	+    ipad &&
1444	+    splashFinished &&
1445	+    matrixClient !== null &&
1446	+    !FULLSCREEN_ROUTES.includes(currentRoute as keyof Routes);
1447	+
1448	+  const transition = useRef(
1449	+    animateParallel(
1450	+      { marginLeft: [0, SIDEBAR_WIDTH] },
1451	+      { duration: 350, easing: Easing.out(Easing.cubic), native: false },
1452	+    ),
1453	+  ).current;
1454	+
1455	+  const routeTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
1456	+
1457	+  const updateRoute = (newRoute: string | undefined) => {
1458	+    currentRouteRef.current = newRoute;
1459	+    setCurrentRoute(newRoute);
1460	+  };
1461	+
1462	+  useEffect(() => {
1463	+    if (!NavigationContainerRef?.isReady()) return;
1464	+    NavigationContainerRef.addListener("state", () => {
1465	+      const newRoute = NavigationContainerRef?.getCurrentRoute()?.name;
1466	+      const prevRoute = currentRouteRef.current;
1467	+
1468	+      if (routeTimeoutRef.current) clearTimeout(routeTimeoutRef.current);
1469	+
1470	+      const isLeavingFullscreen =
1471	+        FULLSCREEN_ROUTES.includes(prevRoute as keyof Routes) &&
1472	+        !FULLSCREEN_ROUTES.includes(newRoute as keyof Routes);
1473	+
1474	+      if (isLeavingFullscreen) {
1475	+        // Delay until the stack pop animation completes (~350ms) so the
1476	+        // marginLeft shift doesn't conflict with the screen transition.
1477	+        routeTimeoutRef.current = setTimeout(() => updateRoute(newRoute), 380);
1478	+      } else {
1479	+        updateRoute(newRoute);
1480	+      }
1481	+    });
1482	+  }, [NavigationContainerRef?.isReady()]);
1483	+
1484	+  useEffect(() => {
1485	+    if (showSidebar) {
1486	+      setTimeout(() => transition.start(), 200);
1487	+    } else transition.reverse();
1488	+  }, [showSidebar]);
1489	+
1490	+  return (
1491	+    <Block flex={1}>
1492	+      <Block flex={1} animations={transition.animations}>
1493	+        {children}
1494	+      </Block>
1495	+      {showSidebar && <IpadSidebar />}
1496	+    </Block>
1497	+  );
1498	+};
