1	import { useIsFocused } from "@react-navigation/native";
2	import {
3	  Membership,
4	  MembershipState_Tags,
5	  StateEventType,
6	} from "@unomed/react-native-matrix-sdk";
7	import { useAtomValue } from "jotai";
8	import { CallAtoms } from "modules/call/jotai";
9	import { CallOverlayService } from "modules/call/service";
10	import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
11	import { NavigationContainerRef } from "modules/navigation/const";
12	import { NetworkAtoms } from "modules/network/jotai";
13	import { useRoomInfo, useRoomMembers } from "modules/room/hooks";
14	import { type FC, useEffect, useMemo, useRef, useState } from "react";
15	import { useSafeAreaInsets } from "react-native-safe-area-context";
16	import { Loading } from "shared/components";
17	import { offlineToastHelper } from "shared/utils";
18	import { RoomBanned, RoomHeader, RoomInvite, RoomTimeline } from "./fragments";
19	
20	interface Props {
21	  roomId: string;
22	  onClose: () => void;
23	}
24	
25	export const RoomBody: FC<Props> = ({ roomId, onClose }) => {
26	  const client = MatrixCore.instance;
27	  const room = useMemo(() => client?.getRoom(roomId), [client, roomId]);
28	  const insets = useSafeAreaInsets();
29	  const roomInfo = useRoomInfo(room);
30	  const isFocused = useIsFocused();
31	  const [isInviteAccepted, setIsInviteAccepted] = useState(false);
32	  const initialMembershipRef = useRef<Membership | null>(null);
33	  const isOffline = useAtomValue(NetworkAtoms.isOffline);
34	  const isRoomInvite = useMemo(() => {
35	    return roomInfo?.membership === Membership.Invited && !isInviteAccepted;
36	  }, [roomInfo, isInviteAccepted]);
37	  const isBanned = roomInfo?.membership === Membership.Banned;
38	  const isKicked = roomInfo?.membership === Membership.Knocked;
39	  const hasOngoingRoomCall = roomInfo?.hasRoomCall ?? false;
40	  const hasActiveCall = useAtomValue(CallAtoms.hasActiveCall);
41	  const hasPowerLevelToCall =
42	    roomInfo?.powerLevels?.canOwnUserSendState(StateEventType.CallMember) ??
43	    false;
44	
45	  const {
46	    members,
47	    isLoading: isMembersLoading,
48	    fetchMembers,
49	  } = useRoomMembers(room);
50	  const roomMembers = useMemo(
51	    () =>
52	      members.filter((m) => m.membership?.tag === MembershipState_Tags.Join)
53	        .length,
54	    [members],
55	  );
56	
57	  useEffect(() => {
58	    if (!roomInfo) return;
59	
60	    if (initialMembershipRef.current === null) {
61	      initialMembershipRef.current = roomInfo.membership;
62	      return;
63	    }
64	
65	    if (
66	      roomInfo.membership === Membership.Left &&
67	      initialMembershipRef.current !== Membership.Left
68	    ) {
69	      onClose();
70	    }
71	  }, [roomInfo?.membership, onClose]);
72	
73	  useEffect(() => {
74	    initialMembershipRef.current = null;
75	    setIsInviteAccepted(false);
76	  }, [roomId]);
77	
78	  const handleStartCall = () => {
79	    if (!client || !room) {
80	      console.error("Client or room not available");
81	      return;
82	    }
83	
84	    if (hasActiveCall) {
85	      offlineToastHelper("You are already in a call");
86	      return;
87	    }
88	
89	    if (isOffline) {
90	      offlineToastHelper("No internet connection");
91	      return;
92	    }
93	
94	    CallOverlayService.openCall(roomId, room.displayName());
95	  };
96	
97	  const handleInviteAccepted = () => {
98	    setIsInviteAccepted(true);
99	  };
100	
101	  const handleRoomDetails = () => {
102	    if (isRoomInvite || !room) return;
103	    NavigationContainerRef.navigate("roomDetails", { room });
104	  };
105	
106	  useEffect(() => {
107	    if (!isFocused) return;
108	    fetchMembers();
109	  }, [isFocused, fetchMembers]);
110	
111	  if (!room) return null;
112	
113	  if (!roomInfo) {
114	    return (
115	      <>
116	        <RoomHeader
117	          room={room}
118	          isMembersLoading={isMembersLoading}
119	          roomMembers={roomMembers}
120	          hasCallOption
121	          topInset={insets.top}
122	          onBack={onClose}
123	        />
124	        <Loading isFullScreen={false} />
125	      </>
126	    );
127	  }
128	
129	  return (
130	    <>
131	      <RoomHeader
132	        room={room}
133	        isDirect={!!roomInfo.isDirect}
134	        isMembersLoading={isMembersLoading}
135	        roomMembers={roomMembers}
136	        hasCallOption={!isRoomInvite && !isBanned && hasPowerLevelToCall}
137	        hasOngoingRoomCall={hasOngoingRoomCall}
138	        hasActiveCall={hasActiveCall}
139	        topInset={insets.top}
140	        onBack={onClose}
141	        onRoomDetails={handleRoomDetails}
142	        onStartCall={handleStartCall}
143	      />
144	
145	      {isBanned || isKicked ? (
146	        <RoomBanned
147	          type={isBanned ? "banned" : "kicked"}
148	          room={room}
149	          onForgotten={onClose}
150	        />
151	      ) : isRoomInvite ? (
152	        <RoomInvite
153	          roomId={roomId}
154	          roomInfo={roomInfo}
155	          memberCount={roomMembers}
156	          onAccepted={handleInviteAccepted}
157	          onDeclined={onClose}
158	        />
159	      ) : (
160	        <RoomTimeline room={room} roomId={roomId} />
161	      )}
162	    </>
163	  );
164	};
