4	} from "@gorhom/bottom-sheet";
5	import { animateSequence, Block } from "@prototyp/skeletor";
6	import {
7	  forwardRef,
8	  type ReactNode,
9	  useCallback,
10	  useEffect,
11	  useImperativeHandle,
12	  useRef,
13	} from "react";
14	import { Dimensions, Modal, Pressable, StyleSheet } from "react-native";
15	import { usePreventSwipeBack } from "shared/hooks";
16	import { Colors } from "shared/styles";
17	import { effectiveWindowWidth, isIpad } from "shared/utils";
18	
19	const { height } = Dimensions.get("screen");
20	
21	export interface AppBottomSheetRef {
22	  close: () => void;
23	}
24	
25	interface Props {
26	  isOpen: boolean;
27	  children: ReactNode;
28	  maxContentSize?: number;
29	  enableContentPanningGesture?: boolean;
30	  keyboardBehavior?: BottomSheetModalProps["keyboardBehavior"];
31	  keyboardBlurBehavior?: BottomSheetModalProps["keyboardBlurBehavior"];
32	  android_keyboardInputMode?: BottomSheetModalProps["android_keyboardInputMode"];
33	  /** Skip the full-screen dim backdrop. Use when the host already provides
34	   *  its own dimmed background (e.g. sheet mounted inside an RN Modal). */
35	  hideBackdrop?: boolean;
36	  onClose: () => void;
37	}
38	
39	export const AppBottomSheet = forwardRef<AppBottomSheetRef, Props>(
40	  (
41	    {
42	      isOpen,
43	      children,
44	      maxContentSize,
45	      enableContentPanningGesture,
46	      keyboardBehavior,
47	      keyboardBlurBehavior,
48	      android_keyboardInputMode,
49	      hideBackdrop,
50	      onClose,
51	    },
52	    ref,
53	  ) => {
54	    const sheetRef = useRef<BottomSheetModal>(null);
55	    const fadeIn = useRef(
56	      animateSequence({ opacity: [0, 1] }, { duration: 200 }),
57	    ).current;
58	    const isClosingRef = useRef(false);
59	
60	    const handleDismiss = useCallback(() => {
61	      if (isClosingRef.current) return;
62	      isClosingRef.current = true;
63	      fadeIn.reverse(() => {
64	        isClosingRef.current = false;
65	        onClose();
66	      });
67	    }, [fadeIn, onClose]);
68	
69	    useImperativeHandle(ref, () => ({
70	      close: () => {
71	        if (isIpad()) {
72	          onClose();
73	          return;
74	        }
75	        handleDismiss();
76	        sheetRef.current?.dismiss();
77	      },
78	    }));
79	
80	    usePreventSwipeBack(isOpen);
81	
82	    useEffect(() => {
83	      if (!isOpen || isIpad()) return;
84	      fadeIn.start();
85	      sheetRef.current?.present();
86	    }, [isOpen, fadeIn]);
87	
