28	export const IpadLayoutWrapper: React.FC<PropsWithChildren> = ({
29	  children,
30	}) => {
31	  const ipad = isIpad();
32	  const splashFinished = useAtomValue(NavigationAtoms.splashFinished);
33	  const matrixClient = useAtomValue(MatrixAtoms.matrixClient);
34	  const [currentRoute, setCurrentRoute] = useState<string | undefined>(
35	    undefined,
36	  );
37	  const currentRouteRef = useRef<string | undefined>(undefined);
38	
39	  const showSidebar =
40	    ipad &&
41	    splashFinished &&
42	    matrixClient !== null &&
43	    !FULLSCREEN_ROUTES.includes(currentRoute as keyof Routes);
44	
45	  const transition = useRef(
46	    animateParallel(
47	      { marginLeft: [0, SIDEBAR_WIDTH] },
48	      { duration: 350, easing: Easing.out(Easing.cubic), native: false },
49	    ),
50	  ).current;
51	
52	  const routeTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
53	
54	  const updateRoute = (newRoute: string | undefined) => {
55	    currentRouteRef.current = newRoute;
56	    setCurrentRoute(newRoute);
57	  };
58	
59	  useEffect(() => {
60	    if (!NavigationContainerRef?.isReady()) return;
61	    NavigationContainerRef.addListener("state", () => {
62	      const newRoute = NavigationContainerRef?.getCurrentRoute()?.name;
63	      const prevRoute = currentRouteRef.current;
64	
65	      if (routeTimeoutRef.current) clearTimeout(routeTimeoutRef.current);
66	
67	      const isLeavingFullscreen =
68	        FULLSCREEN_ROUTES.includes(prevRoute as keyof Routes) &&
69	        !FULLSCREEN_ROUTES.includes(newRoute as keyof Routes);
70	
71	      if (isLeavingFullscreen) {
72	        // Delay until the stack pop animation completes (~350ms) so the
73	        // marginLeft shift doesn't conflict with the screen transition.
74	        routeTimeoutRef.current = setTimeout(() => updateRoute(newRoute), 380);
75	      } else {
76	        updateRoute(newRoute);
77	      }
78	    });
79	  }, [NavigationContainerRef?.isReady()]);
80	
81	  useEffect(() => {
82	    if (showSidebar) {
83	      setTimeout(() => transition.start(), 200);
84	    } else transition.reverse();
85	  }, [showSidebar]);
86	
87	  return (
88	    <Block flex={1}>
89	      <Block flex={1} animations={transition.animations}>
90	        {children}
91	      </Block>
92	      {showSidebar && <IpadSidebar />}
93	    </Block>
94	  );
95	};
